D[43707]={"^Charges the enemy with an unexpected result%.%s*$","Cargas o inimigo com um resultado inesperado."}
D[43708]={"^Deals (.-) Physical damage and knocks back enemies%.%s*$","causa {{1}} de dano Físico e afasta os inimigos."}
D[43709]={"^Spinning round and round!%s*$","Concedendo giros e mais giros!"}
D[43710]={"^In a whirlwind of steel shells, you attack up to (.-) enemies within (.-) yards, causing (.-) Physical damage to each enemy%.%s*$","Em um redemoinho de cápsulas de aço, ataca até {{1}} inimigos em um raio de {{2}} m, causando {{3}} de dano Físico a cada inimigo."}
D[43711]={"^Deals (.-) Fire damage, then deals (.-) Fire damage over (.-) to nearby enemies%.%s*$","causa {{1}} de dano de Fogo, e depois causa {{2}} de dano de Fogo durante {{3}} os inimigos próximos."}
D[43712]={"^Deals (.-) Fire damage to enemies in front of the caster%s*$","causa {{1}} de dano de Fogo aos inimigos frente o conjurador."}
D[43713]={"^Devilsaur roars and deals (.-) Physical damage and silence all enemies in (.-) yards for (.-)%.%s*$","Devilsaur rugirá e causará {{1}} de dano Físico e silenciará todos inimigos em um raio de {{2}} m durante {{3}}."}
D[43714]={"^Deals (.-) damage every (.-) sec for (.-)%. Nearby enemies are also slows them for the duration%.%s*$","Causa {{1}} de dano a cada {{2}} s durante {{3}}. Os inimigos próximos também serão desacelerados durante esse período."}
D[43715]={"^A swirling vortex of souls surrounds the caster, inflicting Shadow damage%.%s*$","Uma voragem giratória de almas ao redor do conjurador, causando dano de Sombra."}
D[43716]={"^Deals (.-)%% weapon damage%.%s*$","causa {{1}}% de dano da arma."}
D[43717]={"^Fires a flaming arrow that explodes on impact%.%s*$","Lança uma flecha em chamas que explode ao impactar."}
D[43718]={"^Inflicts (.-) Fire damage to all enemies in the target area and burns the ground, inflicting (.-) additional Fire damage every (.-) second to enemies within the area for up to (.-)%.%s*$","causa {{1}} de dano de Fogo a todos inimigos na área-alvo e queima o apenas, causando {{2}} de dano adicional de Fogo cada {{3}} segundo os inimigos dentro da zona por até {{4}}."}
D[43719]={"^Attacks nearby enemies in a whirlwind of steel that inflicts (.-)%% Physical damage and knocks back targets%.%s*$","Atinge os inimigos próximos em um redemoinho de aço que causa {{1}}% de dano Físico e afasta aos alvos."}
D[43721]={"^Inflicts (.-)%% of weapon damage to enemies every (.-) secs for (.-)%.%s*$","causa {{1}}% do dano da arma os inimigos a cada {{2}} s durante {{3}}."}
D[43722]={"^Inflicts (.-)%% of weapon damage to enemies%.%s*$","causa {{1}}% do dano da arma os inimigos."}
D[43723]={"^Leap near the enemy%.%s*$","Salta perto do inimigo."}
D[43724]={"^The bananas are going%. You better not be in the way%.%s*$","As bananas se estiverem movendo. Melhor não estiver no caminho."}
