D[47594]={"^Deals (.-)%% off%-hand Weapon Damage%.%s*$","causa {{1}}% do dano da arma secundária."}
D[47596]={"^Increases magic resistances by (.-)%%, and melee haste by (.-)%% for (.-), stacking (.-) times%.%s*$","Aumenta seus resistências mágicos em {{1}}% e sua aceleração de corpo a corpo em {{2}}% durante {{3}}, acumulando-se {{4}} vezes."}
