D[48782]={"^Deals (.-) Fire damage every (.-) second for (.-)%.%s*$","causa {{1}} de dano de Fogo aos inimigos cada {{2}} segundo durante {{3}}."}
D[48783]={"^Inflicts (.-) Fire damage to enemies in a cone in front of the dragonkin and burns them for (.-) Fire damage every (.-) second%.%s*$","Causa {{1}} de dano de Fogo os inimigos em um cone frente o draconiano e os queima em {{2}} de dano de Fogo a cada {{3}} s."}
D[48784]={"^Dealing (.-)%% Weapon damage as Fire damage to the target and up to (.-) nearby targets%.%s*$","causa {{1}}% do dano da arma como dano de Fogo ao alvo e até {{2}} alvos próximos."}
