D[49055]={"^Increases the damage dealt by Hunter shots by (.-)%% for (.-)%. Stacks up to (.-) times%.%s*$","Aumenta o dano dos disparos de Caçador em {{1}}% durante {{2}}. Acumula até {{3}} vezes."}
D[49056]={"^Increase the damage dealt by your Ambush by (.-)%% %((.-)%% versus players%) for (.-)%. Stacks up to (.-) times%.%s*$","Aumenta o dano de seu Emboscada em {{1}}% ({{2}}% contra jogadores) durante {{3}}. Acumula até {{4}} vezes."}
D[49057]={"^Shadow Powers SLS for Duskblade procs%s*$","Potencializador de Sombras SLS para ativações de Duskblade."}
D[49058]={"^While affected by Ironfur healing received is increased by (.-)%%%.%s*$","Enquanto estiver afetado por Pelhejodehierro, a cura recebida aumenta em {{1}}%."}
D[49059]={"^Generate (.-)%% energy whenever you dodge of parry%.%s*$","gera {{1}}% energia sempre quesquivas ou para."}
