D[50198]={"^Equip your Grotesque Banshee's Keening%s*$","equipa seu Lamento de Buhostraedora Gótica."}
D[50199]={"^Summons and dismisses your Nexus Arcanist's Hover Disc%.%s*$","Evoca e dispensa Nexus Arcanist's Hover Disc."}
D[50200]={"^Summons and dismisses your Nexus Spellbinder's Hover Disc%.%s*$","Evoca e dispensa Nexus Spellbinder's Hover Disc."}
