D[53586]={"^Lightning Hands Baby!%s*$","Faz-tudo Relâmpago Que assombro!"}
D[53587]={"^Fel Hands Baby!%s*$","Faz-tudo Fel Que assombro!"}
D[53588]={"^Holy Hands Baby!%s*$","Faz-tudo Sagradas Que assombro!"}
